TER_USER_ID , T1.REGISTER_DATE_TIME , T1.UPDATE_USER_ID , T1.UPDATE_DATE_TIME , (SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = T1.ENT_CODE AND USER_ID = T1.REGISTER_USER_ID) AS REGISTER_USER_NAME , (SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = T1.ENT_CODE AND USER_ID = T1.UPDATE_USER_ID) AS UPDATE_USER_NAME , T1.CUST_CODE_LV1 , T1.DELIVERY_ID , T1.FREE_TRANS_YN , T1.INSURANCE_CUR FROM TB_ECM_LICENSE T1 WHERE T1.ENT_CODE = #{entCode}
