/* LicenseMapper.selectLicenseGoodsItemOdList : 면장 란 - 오더아이템 List */ SELECT ODITEM.HS_CODE , MAX(ODITEM.HBL_NO) HBL_NO , MAX(ODITEM.ITEM_ORGIN_COUNTRY) ORIGIN_COUNTRY , SUM(ODITEM.AMOUNT) DECLARATION_AMOUNT_CUR , MAX(ODITEM.BRAND) BRAND , MAX(ODITEM.DETAIL_ITEM_NAME) DETAIL_ITEM_NAME , SUM(ODITEM.PIECES) PIECES , MAX(ODITEM.UNIT_PIECES) UNIT_PIECES , 'KG' UNIT_WEIGHT , SUM(ODITEM.NWT) NWT , MAX(ODITEM.CURRENCY_CODE) CURRENCY_CODE , SUM(ODITEM.UNIT_PRICE) UNIT_PRICE , MAX(ODITEM.ITEM_URL) ITEM_URL , MAX(ODITEM.ITEM_CODE) ITEM_CODE FROM TB_ECM_OD_ITEM ODITEM WHERE 1=1
AND ODITEM.OD_JOB_NO = #{srchOdJobNo}
GROUP BY ODITEM.HS_CODE

/* LicenseMapper.selectLicenseCommodityItemOdList : 면장 규격 - 오더아이템 List */ SELECT ODITEM.HS_CODE , SUM(ODITEM.AMOUNT) DECLARATION_AMOUNT_CUR , MAX(ODITEM.DETAIL_ITEM_NAME) DETAIL_ITEM_NAME , SUM(ODITEM.PIECES) PIECES , MAX(ODITEM.UNIT_PIECES) UNIT_PIECES , 'KG' UNIT_WEIGHT , SUM(ODITEM.NWT) NWT , MAX(ODITEM.CURRENCY_CODE) CURRENCY_CODE , SUM(ODITEM.UNIT_PRICE) UNIT_PRICE , ODITEM.ITEM_CODE , MAX(ODITEM.ITEM_URL) ITEM_URL , MAX(ODITEM.ITEM_SIZE) ITEM_SIZE FROM TB_ECM_OD_ITEM ODITEM WHERE 1=1
AND ODITEM.OD_JOB_NO = #{srchOdJobNo}
GROUP BY ODITEM.HS_CODE, ODITEM.ITEM_CODE

/* LicenseMapper.selectLicenseGoodsItemList : 면장 란 List */ SELECT LICENSE_JOB_NO , SEQ_NO_ID , HS_CODE , BRAND , DETAIL_ITEM_NAME , PIECES , UNIT_PIECES , NWT , UNIT_WEIGHT , PACKING_PIECES , UNIT_PACKING , DECLARATION_AMOUNT_LOC , DECLARATION_AMOUNT_CUR , DECLARATION_AMOUNT_USD , LICENSE_PAY_AMOUNT_LOC , HBL_NO , ORIGIN_COUNTRY , ADJUST_AMOUNT_LOC , MAKER_TYPE , AUTO_REFUND_TYPE , CURRENCY_CODE FROM TB_ECM_LICENSE_GOODS_ITEM WHERE 1=1
AND LICENSE_JOB_NO = #{licenseJobNo}
AND SEQ_NO_ID = #{seqNoId}
AND HS_CODE = #{hsCode}

/* LicenseMapper.selectLicenseCommodityItemList : 면장 규격 List */ SELECT LICENSE_JOB_NO , SEQ_NO_ID , CMDITY_SEQ_NO_ID , BRAND , DETAIL_ITEM_NAME , PIECES , UNIT_PIECES , ITEM_CODE , UNIT_PRICE_CUR , UNIT_PRICE_LOC , AMOUNT_CUR , AMOUNT_LOC , NWT , UNIT_WEIGHT , ITEM_URL , ITEM_SIZE , HS_CODE , ADJUST_AMOUNT_LOC FROM TB_ECM_LICENSE_COMMODITY_ITEM WHERE 1=1
AND LICENSE_JOB_NO = #{licenseJobNo}
AND SEQ_NO_ID = #{seqNoId}
AND CMDITY_SEQ_NO_ID = #{cmditySeqNoId}

