/* LicenseMapper.selectLicenseExcelList : 면장 엑셀 List */
SELECT LC.PO_NO ,LCCMDT.LICENSE_JOB_NO ,LCCMDT.ITEM_CODE ,LCCMDT.DETAIL_ITEM_NAME ,CONVERT(NUMERIC (5,2), LCCMDT.NWT) AS NWT ,CONVERT(VARCHAR, CAST(LC.LICENSE_PAY_AMOUNT_CUR AS NUMERIC(9,2))) AS LICENSE_PAY_AMOUNT_CUR ,CONVERT(VARCHAR, CAST(LC.UNIT_PRICE_CUR AS NUMERIC(9,2))) AS UNIT_PRICE_CUR
,LCCMDT.PIECES ,LC.CURRENCY_CODE ,LC.CONSIGNEE_NAME ,LC.DEST_COUNTRY ,LCGOODS.HS_CODE ,LCGOODS.ORIGIN_COUNTRY ,LC.DELIVERY_TYPE_CODE ,LC.DEST_PORT ,LC.CONSIGNEE_ZIPCODE ,LC.CONSIGNEE_ADDRESS ,LC.CONSIGNEE_TEL ,LC.MAKER_NAME ,LC.MAKER_BUSINESS_ID ,LC.MAKER_CUSTOMS_ID ,LC.MAKER_ZIPCODE ,LC.INCOTERMS ,LC.DELIVERY_FEE_LOC ,LC.INSURANCE_LOC ,LC.LICENSE_PAY_METHOD ,LC.LICENSE_REMARK ,LC.LICENSE_CUSTOMS_CODE ,LC.LICENSE_CUSTOMS_DPT_CODE ,LC.GOODS_LOC_ZIPCODE ,LC.GOODS_LOC_ADDRESS ,LC.BWH_NAME ,LCCMDT.CMDITY_SEQ_NO_ID ,LC.FREE_TRANS_YN ,LC.DELIVERY_ID ,LC.HBL_NO ,LC.EXPRESS_SIGN ,LCCMDT.BRAND ,LC.ADJUST_AMOUNT_LOC ,LCCMDT.ITEM_URL ,LCCMDT.ITEM_SIZE ,DENSE_RANK() OVER (ORDER BY LC.PO_NO) AS SEQ ,LC.DECLARATION_NAME ,LC.PO_DATE ,LC.AGENT_NAME ,LC.AGENT_CUSTOMS_ID ,LC.SHIPPER_BUSINESS_NAME ,LC.SHIPPER_BUSINESS_PRESIDENT ,LC.SHIPPER_BUSINESS_ADDRESS ,LC.SHIPPER_BUSINESS_ZIPCODE ,LC.SHIPPER_BUSINESS_ID ,LC.SHIPPER_BUSINESS_CUSTOMS_ID ,LCGOODS.PACKING_PIECES , LCCMDT.UNIT_PRICE_LOC * LCCMDT.PIECES AMOUNT_TOTAL , (LCCMDT.UNIT_PRICE_LOC * LCCMDT.PIECES) - LC.ADJUST_AMOUNT_LOC + LC.DELIVERY_FEE_LOC LICENSE_PAY_AMOUNT , '제조사 미상' MAKER_NAME_NONE FROM TB_ECM_LICENSE_COMMODITY_ITEM LCCMDT INNER JOIN TB_ECM_LICENSE_GOODS_ITEM LCGOODS ON LCCMDT.LICENSE_JOB_NO = LCGOODS.LICENSE_JOB_NO AND LCCMDT.SEQ_NO_ID = LCGOODS.SEQ_NO_ID INNER JOIN TB_ECM_LICENSE LC ON LCGOODS.LICENSE_JOB_NO = LC.LICENSE_JOB_NO WHERE LC.ENT_CODE = #{entCode}
AND LC.${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND LC.${srchDateGbn} <= DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND LC.${srchLicenseType} LIKE CONCAT('%',#{srchLicenseText},'%')
AND LC.LICENSE_TYPE = #{licenseType}
AND LCCMDT.LICENSE_JOB_NO IN (#{item})
AND LC.RESULT_STATUS = #{srchResultStatus}
AND LC.SEND_RESULT_CODE = #{srchSendResultCode}

mapper.update:
/* LicenseMapper.updateLicenseSendResult : 면장 전송API 결과 UPDATE */
UPDATE
		TB_ECM_LICENSE
	SET 
		SEND_RESULT_CODE = #{sendResultCode}
		
		,EFN_PO_NO = #{efnPoNo}
		
		,SEND_RESULT_ERROR_DESC = #{sendResultErrorDesc}
		,SEND_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
		,UPDATE_USER_ID = #{updateUserId}
		,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
  WHERE
  		PO_NO = #{poNo}	
  		AND LICENSE_TYPE = #{licenseType}

mapper.select:
/* LicenseMapper.selectLienseCount : 면장 검색 건수조회 */
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
	SELECT COUNT(*) CNT
		FROM TB_ECM_LICENSE T1
	WHERE T1.ENT_CODE = #{entCode}

/** LicenseMapper.selectBusinessApiKeyInfo : 사업장 API 키 조회  */
SELECT
	IF_SVR_ID
	,IF_SVR_PW
	,IF_WEB_ID
	,IF_WEB_PWD
  FROM
  	TB_SMS_ENT_BUSINESS_INTERFACE
 WHERE
 	ENT_CODE = #{entCode}
 	AND ENT_BUSINESS_CODE = #{entBusinessCode}
 	AND IF_SERVICE_CODE = #{ifServiceCode}

/** LicenseMapper.selectCustomerApiKeyInfo : 거래처 API 키 조회  */
SELECT
	IF_LOGIN_ID
	,IF_LOGIN_PW
  FROM
  	TB_SMS_CUSTOMER_INTERFACE
 WHERE
 	ENT_CODE = #{entCode}
 	AND IF_SERVICE_CODE = #{ifServiceCode} 		
 	AND CUSTOMER_CODE = #{customerCode}

mapper.insert:
/** LicenseMapper.insertLicenseOd : 오더 License 테이블에 면장정보 INSERT */
INSERT INTO TB_ECM_OD_LICENSE
(
	OD_JOB_NO
	,LICENSE_NO
	,PIECES
	,UNIT_PIECES
	,GWT
	,EFN_PO_NO
	,EFN_SENDER_CODE
	,EFN_DELIVERY_NO
	,REGISTER_USER_ID
	,REGISTER_DATE_TIME
	,UPDATE_USER_ID
	,UPDATE_DATE_TIME 
)
VALUES
(	
	#{odJobNo}
	,#{licenseNo}
	,#{pieces}
	,#{unitPieces}
	,#{gwt}
	,#{poNo}
	,#{efnSenderCode}
	,#{hblNo}
	,#{updateUserId}
	,DATEADD(HOUR, ${gmtTime}, GETDATE())
	,#{updateUserId}
	,DATEADD(HOUR, ${gmtTime}, GETDATE())	
)

mapper.delete:
/** LicenseMapper.deleteLicenseOd : TB_ECM_OD_LICENSE 면장정보 삭제 */
DELETE FROM TB_ECM_OD_LICENSE 
WHERE OD_JOB_NO  = #{odJobNo}

mapper.select:
/** LicenseMapper.selectLicenseSendList : E면장 전송할 면장 List 조회 */
SELECT
		EFN_PO_NO
		,PO_NO
  FROM
  		TB_ECM_LICENSE
 WHERE	
 		SEND_RESULT_CODE = #{sendResultCode}
 		AND EFN_PO_NO IS NOT NULL 
 		AND LICENSE_TYPE = #{licenseType}

mapper.update:
/* LicenseMapper.updateLicenseResultStatus : 면장 수신결과 UPDATE */
UPDATE
		TB_ECM_LICENSE
	SET 
		RESULT_STATUS = #{resultStatus}
		,RESULT_ERROR_REASON = #{resultErrorReason}
		,SEND_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
		,UPDATE_USER_ID = #{updateUserId}
		,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
  WHERE LICENSE_TYPE = #{licenseType}	
  	
  		
  		AND LICENSE_JOB_NO IN(#{item})
  		
  		
	  		
	        	
					AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
	        	
	        	
					AND ${srchDateGbn} <= DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
				
				
			
				
					
					AND ${srchLicenseType} IN (#{item})
					
					
					AND ${srchLicenseType} = #{srchLicenseText}
					
				
			
			
				AND CUST_CODE_LV1 = #{srchCustCodeLv1}
				
			
				AND RESULT_STATUS = #{srchResultStatus}
				
			
				
					
					AND SEND_RESULT_CODE IS NULL OR SEND_RESULT_CODE = ''
					
					
					AND SEND_RESULT_CODE = #{srchSendResultCode}
